require('dotenv').config();
const express = require('express');
const path = require('path');
const cookieParser = require('cookie-parser');
const expressLayouts = require('express-ejs-layouts');
const connectDB = require('./config/db');

// Generated by GitHub Copilot - Oct-17-2026
const { validateOtpConfig } = require('./utils/otpService');
validateOtpConfig();

const pageRoutes = require('./routes/pageRoutes');
const authApiRoutes = require('./routes/authRoutes');
const complaintPageRoutes = require('./routes/complaintPageRoutes');
const complaintApiRoutes = require('./routes/complaintApiRoutes');
const adminPageRoutes = require('./routes/adminPageRoutes');
const adminApiRoutes = require('./routes/adminApiRoutes');
const villageApiRoutes = require('./routes/villageApiRoutes');

const app = express();

connectDB();

// View engine
app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));
app.use(expressLayouts);
app.set('layout', 'partials/layout');

// Core middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());
app.use(express.static(path.join(__dirname, 'public')));

// Make current user available in every view (defaults to null pre-auth)
app.use((req, res, next) => {
  res.locals.currentUser = res.locals.currentUser || null;
  next();
});

// ---- Page routes ----
app.use('/', pageRoutes);
app.use('/complaints', complaintPageRoutes);
app.use('/admin', adminPageRoutes);

// ---- REST API routes (SRS Section 6) ----
app.use('/api/v1/auth', authApiRoutes);
app.use('/api/v1/complaints', complaintApiRoutes);
app.use('/api/v1/admin', adminApiRoutes);
app.use('/api/v1/villages', villageApiRoutes); // used by the Android app (registration + filters)

// 404 handler
app.use((req, res) => {
  res.status(404).render('404', { title: 'Not Found' });
});

// Error handler
app.use((err, req, res, next) => {
  console.error(err);
  if (req.originalUrl.startsWith('/api/')) {
    return res.status(500).json({ error: err.message || 'Server error' });
  }
  res.status(500).send(`<pre>Server error: ${err.message}</pre>`);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`\nAkole Taluka CCMS running -> http://localhost:${PORT}\n`);
});
